import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_cube(n):
    if n < 0:
        return False
    if n == 0:
        return True
    # Calculate the integer cube root (closest integer)
    p_approx = round(n**(1/3))
    p = int(p_approx)
    return p * p * p == n, p

q_values = [2, 3, 5, 7, 11]
results = []

for q in q_values:
    X = q**2 - q + 1
    is_cube, p = is_perfect_cube(X)

    result_entry = {
        'q': q,
        'X': X,
        'is_cube': is_cube,
        'p': p,
        'valid': False
    }

    if is_cube:
        # Check if p is prime and p != q
        if is_prime(p) and p != q:
            result_entry['valid'] = True

    results.append(result_entry)

for r in results:
    print(f"q={r['q']}: X = {r['X']}. Is perfect cube? {r['is_cube']}. p={r['p']}. Valid solution? {r['valid']}")

import math

def check_cube(N):
    if N < 0:
        return None
    k = round(N**(1/3))
    if k**3 == N:
        return k
    return None

def check_primes(limit):
    primes = []
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for multiple in range(p*p, limit + 1, p):
                is_prime[multiple] = False
    return primes

primes = check_primes(30)
print(f"Primes up to 30: {primes}")

results = {}
for q in primes:
    N = q**2 - q + 1
    k = check_cube(N)
    results[q] = k

print("\nResults for q^2 - q + 1 being a perfect cube:")
for q, k in results.items():
    if k is not None:
        print(f"q={q}: N={q**2 - q + 1} = {k}^3")
    else:
        print(f"q={q}: N={q**2 - q + 1} (Not a perfect cube)")

